}
 $productionUserIds=implode(',',array_map(static fn(array$row):int=>(int)$row['id'],$users));$productionRoleIds=implode(',',array_keys($roleIds));$target->query("DELETE FROM `{$prefix}fm2_pilot_users` WHERE user_id<9000000000 AND user_id NOT IN ({$productionUserIds})");$target->query("DELETE FROM `{$prefix}fm2_pilot_roles` WHERE role_id<9000 AND role_id NOT IN ({$productionRoleIds})");$target->query("DELETE ur FROM `{$prefix}fm2_pilot_user_roles` ur LEFT JOIN `{$prefix}fm2_pilot_users` u ON u.user_id=ur.user_id LEFT JOIN `{$prefix}fm2_pilot_roles` r ON r.role_id=ur.role_id WHERE u.user_id IS NULL OR r.role_id IS NULL");$target->query("DELETE FROM `{$prefix}fm2_pilot_user_roles` WHERE origin='legacy_primary'");$seed=$target->prepare("INSERT INTO `{$prefix}fm2_pilot_user_roles`(user_id,role_id,origin,assigned_at,assigned_by_user_id) VALUES(?,?,'legacy_primary',?,NULL) ON DUPLICATE KEY UPDATE origin=IF(origin='legacy_primary',VALUES(origin),origin)");$seeded=0;foreach($users as$row){$userId=(int)$row['id'];$roleId=(int)$row['role_id'];if(!isset($roleIds[$roleId]))continue;$seed->bind_param('iis',$userId,$roleId,$now);$seed->execute();$seeded++;}$target->query("INSERT IGNORE INTO `{$prefix}fm2_process_user_capabilities`(user_id,capability,position_snapshot) SELECT ur.user_id,'assignment_order.prepare',NULL FROM `{$prefix}fm2_pilot_user_roles` ur JOIN `{$prefix}fm2_pilot_roles` r ON r.role_id=ur.role_id WHERE r.status=1 AND LOWER(r.name) IN ('администратор','суперадминистратор','администратор пилота')");$target->commit();
}catch(Throwable $error){$target->rollback();throw$error;}
